import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) nextLong();
        long[] a = new long[n];
        long total = 0;
        for (int i = 0; i < n; i++) total += a[i] = nextLong();
        long left = 0, answer = 0;
        // Split after index i for i in 0..n-2: left part non-empty, right part non-empty.
        for (int i = 0; i + 1 < n; i++) {
            left += a[i];
            if (left > total - left) answer++;
        }
        System.out.println(answer);
    }
}

