import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	a := make([]int64, n)
	var total int64
	for i := range a {
		fmt.Fscan(in, &a[i])
		total += a[i]
	}
	var left, answer int64
	// Split after index i for i in 0..n-2: left part non-empty, right part non-empty.
	for i := 0; i+1 < n; i++ {
		left += a[i]
		if left > total-left {
			answer++
		}
	}
	fmt.Println(answer)
}
